from z3 import *

def solve_bibd(v, b, r, k, lam):
    X = [[Int(f"x_{i}_{j}") for j in range(b)] for i in range(v)]
    s = Solver()

    for i in range(v):
        for j in range(b):
            s.add(Or(X[i][j] == 0, X[i][j] == 1))

    for j in range(b):
        s.add(Sum([X[i][j] for i in range(v)]) == k)

    for i in range(v):
        s.add(Sum([X[i][j] for j in range(b)]) == r)

    for i1 in range(v):
        for i2 in range(i1 + 1, v):
            s.add(Sum([X[i1][j] * X[i2][j] for j in range(b)]) == lam)

    # Symmetry breaking
    # Sort columns lexicographically
    for j in range(b - 1):
        # X[][j] >= X[][j+1] lexicographically
        # We can encode this by comparing the integer value of the column
        val1 = Sum([X[i][j] * (2**i) for i in range(v)])
        val2 = Sum([X[i][j+1] * (2**i) for i in range(v)])
        s.add(val1 >= val2)

    print("Solving...")
    s.set("timeout", 30000)
    if s.check() == sat:
        m = s.model()
        res = [[m[X[i][j]].as_long() for j in range(b)] for i in range(v)]
        print("SAT")
        print(res)
    else:
        print("UNSAT or TIMEOUT")

solve_bibd(10, 30, 9, 3, 2)

